import json
import os
import sys
from decimal import Decimal

FACT_MAP = {
    "usa.period_3y": {
        "performance start": ("usaspending_awards", "period_of_performance.start_date"),
        "performance end": ("usaspending_awards", "period_of_performance.end_date"),
    },
    "usa.obligated_95": {
        "amount obligated": ("usaspending_awards", "total_obligation"),
        "potential value": ("usaspending_awards", "base_and_all_options"),
    },
}

DATE_FACTS = {"performance start", "performance end"}


def get_field(obj, path):
    parts = path.split(".")
    val = obj
    for part in parts:
        if isinstance(val, dict):
            val = val.get(part)
        else:
            return None
    return val


def format_value(fact_name, value):
    if fact_name in DATE_FACTS:
        if isinstance(value, str):
            return value[:10]
        return str(value)
    else:
        if isinstance(value, Decimal):
            return str(value)
        elif isinstance(value, float):
            return repr(value)
        elif isinstance(value, int):
            return str(value)
        return str(value)


def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path) as f:
        manifest = json.load(f)

    documents = {}
    for rule_id, facts in FACT_MAP.items():
        for fact_name, (doc, field_path) in facts.items():
            if doc not in documents:
                doc_path = os.path.join(packet_dir, doc + ".json")
                if os.path.exists(doc_path):
                    with open(doc_path) as f:
                        documents[doc] = json.load(f, parse_float=Decimal)
                else:
                    documents[doc] = None

    doc_indexes = {}
    for doc, data in documents.items():
        if data is None:
            doc_indexes[doc] = {}
            continue
        index = {}
        if isinstance(data, list):
            for record in data:
                uid = record.get("generated_unique_award_id")
                if uid:
                    index.setdefault(uid, []).append(record)
        doc_indexes[doc] = index

    result = {}

    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)
        fact_names = manifest["facts"].get(rule_id, [])

        pair_result = {}
        for fact_name in fact_names:
            if rule_id not in FACT_MAP or fact_name not in FACT_MAP[rule_id]:
                pair_result[fact_name] = "ABSENT"
                continue

            doc, field_path = FACT_MAP[rule_id][fact_name]
            index = doc_indexes.get(doc, {})
            matching = index.get(entity, [])

            values = []
            for record in matching:
                val = get_field(record, field_path)
                if val is not None:
                    values.append(val)

            if not values:
                pair_result[fact_name] = "ABSENT"
            else:
                first = values[0]
                all_equal = all(v == first for v in values)
                if all_equal:
                    pair_result[fact_name] = [format_value(fact_name, first), doc]
                else:
                    pair_result[fact_name] = "CONFLICT"

        result[pair] = pair_result

    print(json.dumps(result))


if __name__ == "__main__":
    main()

import json
import os
import sys
from decimal import Decimal

def format_amount(value):
    if value is None:
        return None
    d = Decimal(str(value))
    return str(d)

def get_field_value(award, fact_name, rule_id):
    if rule_id == "usa.period_3y":
        pop = award.get("period_of_performance") or {}
        if fact_name == "performance start":
            val = pop.get("start_date")
            return val if val is not None and val != "" else None
        elif fact_name == "performance end":
            val = pop.get("end_date")
            return val if val is not None and val != "" else None
    elif rule_id == "usa.obligated_95":
        if fact_name == "amount obligated":
            return format_amount(award.get("total_obligation"))
        elif fact_name == "potential value":
            return format_amount(award.get("base_and_all_options"))
    return None

def find_file(packet_dir, base_name):
    for fname in os.listdir(packet_dir):
        if os.path.splitext(fname)[0] == base_name:
            return os.path.join(packet_dir, fname)
    return None

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path) as f:
        manifest = json.load(f)

    awards_path = find_file(packet_dir, "usaspending_awards")
    with open(awards_path) as f:
        awards = json.load(f)

    awards_by_id = {}
    for award in awards:
        uid = award.get("generated_unique_award_id")
        if uid:
            awards_by_id.setdefault(uid, []).append(award)

    result = {}

    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)
        facts = manifest["facts"].get(rule_id, [])

        fact_results = {}
        matching_awards = awards_by_id.get(entity, [])

        for fact_name in facts:
            values = []
            for award in matching_awards:
                val = get_field_value(award, fact_name, rule_id)
                if val is not None:
                    values.append(val)

            if not values:
                fact_results[fact_name] = "ABSENT"
            elif len(set(values)) == 1:
                fact_results[fact_name] = [values[0], "usaspending_awards"]
            else:
                fact_results[fact_name] = "CONFLICT"

        result[pair] = fact_results

    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

