import json
import os
import sys
from decimal import Decimal

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path) as f:
        manifest = json.load(f)

    pairs = manifest["pairs"]
    facts_by_rule = manifest["facts"]

    awards_path = os.path.join(packet_dir, "usaspending_awards.json")
    with open(awards_path) as f:
        awards = json.load(f)

    awards_by_id = {}
    for award in awards:
        award_id = award.get("generated_unique_award_id")
        if award_id:
            awards_by_id.setdefault(award_id, []).append(award)

    result = {}

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        fact_names = facts_by_rule.get(rule_id, [])
        result[pair] = {}

        for fact_name in fact_names:
            values = []

            if entity in awards_by_id:
                for award in awards_by_id[entity]:
                    doc = "usaspending_awards"

                    if rule_id == "usa.period_3y":
                        if fact_name == "performance start":
                            val = award.get("period_of_performance", {}).get("start_date")
                            if val is not None:
                                values.append((val, doc))
                        elif fact_name == "performance end":
                            val = award.get("period_of_performance", {}).get("end_date")
                            if val is not None:
                                values.append((val, doc))
                    elif rule_id == "usa.obligated_95":
                        if fact_name == "amount obligated":
                            val = award.get("total_obligation")
                            if val is not None:
                                values.append((str(Decimal(str(val))), doc))
                        elif fact_name == "potential value":
                            val = award.get("base_and_all_options")
                            if val is not None:
                                values.append((str(Decimal(str(val))), doc))

            if len(values) == 0:
                result[pair][fact_name] = "ABSENT"
            elif len(values) == 1:
                result[pair][fact_name] = [values[0][0], values[0][1]]
            else:
                unique_values = set(v[0] for v in values)
                if len(unique_values) == 1:
                    result[pair][fact_name] = [values[0][0], values[0][1]]
                else:
                    result[pair][fact_name] = "CONFLICT"

    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

